SELECT DATE(e.start_time) AS label,
       COUNT(*)            AS value
FROM adm_encounter e
WHERE e.is_deleted = 0
  AND e.class_enum = 'AMB'
  AND e.start_time >= #{dateFrom}
  AND e.start_time < #{dateTo}

  AND e.organization_id = #{organizationId}

GROUP BY DATE(e.start_time)
ORDER BY label

SELECT DATE(e.start_time) AS label,
       COUNT(*)            AS value
FROM adm_encounter e
WHERE e.is_deleted = 0
  AND e.class_enum = 'AMB'
  AND e.start_time >= #{dateFrom}
  AND e.start_time < #{dateTo}

  AND e.organization_id = #{organizationId}

GROUP BY DATE(e.start_time)
ORDER BY label

SELECT IF(d.description IS NULL OR d.description = '', '其他症状', d.description) AS name, COUNT(DISTINCT e.patient_id) AS value FROM adm_encounter e JOIN adm_encounter_diagnosis d ON e.id = d.encounter_id WHERE e.is_deleted = 0 AND d.is_deleted = 0 AND e.class_enum = 'AMB' AND e.start_time >= #{dateFrom} AND e.start_time < #{dateTo}
AND e.organization_id = #{organizationId}
GROUP BY IF(d.description IS NULL OR d.description = '', '其他症状', d.description) ORDER BY value DESC
